公開response/errorの完全契約（T2/T10と同一）:

```typescript
export interface BatchAccepted {batch_id:string;job_ids:string[];epoch:string;revision:number}
export interface RequestLookup {batch_id:string;job_ids:string[]}
export type CancelMode = 'single'|'queued'|'all'
export type CancelScope = 'all'|'normal'
export type ActionOutcome = 'confirmed'|'unconfirmed'|'failed'|'not_requested'|'skipped'
export interface CancelTarget {job_id?:string;prompt_id?:string}
export interface CancelRequest {mode:CancelMode;scope?:CancelScope;target?:CancelTarget}
export interface CancelResult {
 job_id:string|null;prompt_id:string|null;status:JobStatus|null
 outcome:'cancelled'|'not_cancelled'|'already_terminal'|'unconfirmed'|'rejected';message:string
}
export interface CancelOperation {
 scope:CancelScope;message:string;mode:CancelMode;items:CancelResult[];upstream_clear:ActionOutcome;upstream_interrupt:ActionOutcome;epoch:string;revision:number
}
export interface UpstreamQueueView {
 running:Array<{prompt_id:string;client_id:string|null}>
 pending:Array<{prompt_id:string;client_id:string|null}>
}
export interface ImageIdentity {filename:string;subfolder:string;type:string}
export interface ImageAvailability {availability:'present'|'missing'|'unknown'}

export interface ErrorDetail {
 code:string;message:string;outcome:'failed'|'unconfirmed'|null;request_id:string|null;job_id:string|null
}
export interface ErrorEnvelope {detail:ErrorDetail}
export class GenerationApiError extends Error {
 readonly status:number
 readonly detail:ErrorDetail
 constructor(status:number, detail:ErrorDetail) { super(detail.message);this.status=status;this.detail=detail }
}
// JobView/GenerationSnapshotの共通項目は上記既存interfaceのままPython DTOと同一。
// submitBatch -> BatchAccepted; getRequest -> RequestLookup; cancelJob -> CancelResult
// cancel -> CancelOperation; getUpstreamQueue -> UpstreamQueueView (失敗503); imageAvailability -> ImageAvailability。
// availability -> JobView['outputs']; preview HTTP200は画像bytes/MIME（JSONではない）。
// 409/422/503/404はErrorEnvelope。通信失敗・非JSON旧エラーは同じErrorDetailへ正規化。
// nullable項目は必ずnullとして受信、versionは1以外を型castで通さずruntime検証。
```

同originパス、signal、202/409/503の型、結果照会、元params false/0/空を保持。
